import { etsyGet, etsyPost, SHOP_ID } from "./etsy";

// ─── AGENT 1: MARKET RESEARCH ─────────────────────────────────────────────────
export async function marketResearchAgent(): Promise<{ trending: TrendingNiche[]; recommendations: string[] }> {
  const { results: listings } = await etsyGet(`/application/shops/${SHOP_ID}/listings?state=active&limit=25`).catch(() => ({ results: [] }));

  const existingTitles = listings.map((l: any) => l.title).join(", ") || "none yet";

  const res = await fetch("https://inference-api.nousresearch.com/v1/chat/completions", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-api-key": process.env.AI_PROXY_KEY!,
      "anthropic-version": "2025-03-01",
    },
    body: JSON.stringify({
      model: "hermes-3-mini-128k",
      max_tokens: 1500,
      system: `You are a market research agent for an Etsy store selling digital products and print-on-demand items.
Your job is to identify trending niches and product opportunities that will generate sales.
Focus on: digital downloads (PDFs, templates, planners, guides, SVGs), and POD products (t-shirts, mugs, tote bags, phone cases).
Current store listings: ${existingTitles}
Research high-demand, low-competition niches on Etsy right now.`,
      messages: [{ role: "user", content: `Identify 5 trending Etsy niches for digital products and POD right now. For each niche provide specific product ideas.
Return JSON: { "trending": [{"niche": "", "demand": "high|medium", "competition": "low|medium|high", "products": ["", ""], "avg_price": "", "keywords": ["", ""], "avg_price": ""}], "recommendations": ["action1", "action2"] }` }],
    }),
  });
  const data = await res.json();
  if (data.error) throw new Error(data.error.message);
  const text = data.content[0].text;
  const match = text.match(/\{\[\s\S]*\}|\[\[\s\S]*\]/);
  if (!match) throw new Error("No JSON found in response");
  return JSON.parse(match[0]) as { trending: TrendingNiche[]; recommendations: string[] };
}
